<template>
  <div class="search">
    <div class="search-input">
      <div class="input-box">
        <i class="icon iconfont search">&#xe61a;</i>
        <input class="input" type="text" placeholder="请输入商品名称" v-model="searchKey" @input="searchInput">
        <i class="icon iconfont clear" v-show="searchKey" @click="clearInput">&#xe61f;</i>
      </div>
      <div class="btn" @click="searchHandle('')">搜索</div>
    </div>
    <div class="mescroll search-list" ref="mescroll">
      <div>
        <div class="list">
          <div class="goods-item" v-for="(item, index) in goodsList" :key="index" @click="checkGoodsDetail(item.goods_id)">
            <div class="img-box">
              <img class="goods-img" :src="item.image" alt="">
              <span class="icon txt-icon new-user" v-if="item.is_new_user == 1">新人专享</span>
              <img class="icon" v-else-if="item.labels && item.labels.type == 1" :src="item.labels.image" alt="">
              <span class="icon txt-icon" :style="{background:'-webkit-linear-gradient(top,'+ item.labels.color +','+ item.labels.color2 +')'}" v-else-if="item.labels && item.labels.type == 0">{{item.labels.name}}</span>
            </div>
            <div class="desc-box">
              <div class="name">{{ item.limit_buy == 0 ? '' : '【限购'+item.limit_buy+'份】' }}{{item.name}}</div>
              <div class="total-buy">累计148件</div>
              <div class="price-box">
                <div>
                  <span class="now now-icon main-color-font">¥</span>
                  <span class="now main-color-font">{{item.price}}</span>
                  <span class="old">¥{{item.old_price}}</span>
                </div>
                <AddToCart type="big" :goodsId="item.goods_id" />
              </div>
            </div>
          </div>
        </div>
        <div class="history-box" v-show="goodsList.length == 0 && keyList.length > 0 && !searchKey">
          <div class="title">
            <span>历史搜索</span>
            <span class="btn" @click="clearHistory"><i class="icon iconfont">&#xe68e;</i>清空历史记录</span>
          </div>
          <div class="key-list">
            <span class="item" v-for="(item, index) in keyList" :key="index" @click="searchHandle(item)">{{item}}</span>
          </div>
        </div>
        <div class="empty-list" v-show="searchKey && goodsList.length == 0 && isComplete">
          <div class="empty-tip">
            <div class="img-box"><img src="./imgs/search.png" alt=""></div>
            <div>未搜索到您想要的商品，换个关键词试试~</div>
          </div>
          <DiscountGoods />
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import MeScroll from 'mescroll.js'
import DiscountGoods from '../../components/DiscountGoods/DiscountGoods'
import AddToCart from '../../components/AddToCart/AddToCart'
export default {
  name: 'Search',
  data () {
    return {
      searchKey: '',
      keyList: [],
      leader_id: '',
      page: 1,
      isComplete: false,
      goodsList: [], // 搜索的商品列表
      isSearching: false,
      pageScroll: ''
    }
  },
  created () {
    let keyList = this.$util.storage.get('search_history')
    if (keyList) {
      this.keyList = keyList
    }
    this.leader_id = this.$util.storage.get('leader_id')
  },
  mounted () {
    this.initialScroll()
  },
  methods: {
    // 查看商品详情
    checkGoodsDetail (id) {
      this.$router.push({ path: '/goods', query: { goodsId: id, leaderId: this.leader_id } })
    },
    // 监听输入
    searchInput () {
      if (this.searchKey == '') {
        this.isComplete = false
        this.page = 1
        this.goodsList = []
      }
    },
    // 点击搜索 或者 历史搜索关键字
    searchHandle (key) {
      if (key !== '') {
        this.searchKey = key
        this.isComplete = false
        this.page = 1
      }
      this.searchKey = this.searchKey.replace(/^\s*|\s*$/g, '')
      if (this.searchKey == '') {
        console.log('22222222222228888', this.searchKey)
        return
      }
      this.getGoods()
      let isExist = false
      for (let i = 0; i < this.keyList.length; i++) {
        if (this.keyList[i] == this.searchKey) {
          isExist = true
          this.keyList.splice(i, 1)
          this.keyList.splice(0, 0, this.searchKey)
          break
        }
      }
      if (!isExist) {
        this.keyList.splice(0, 0, this.searchKey)
      }
      this.$util.storage.set('search_history', this.keyList)
    },
    // 点击叉号 清除输入框
    clearInput () {
      this.searchKey = ''
      this.goodsList = []
    },
    // 清除历史记录
    clearHistory () {
      this.keyList = []
      this.$util.storage.set('search_history', this.keyList)
    },
    // 获取商品列表
    async getGoods () {
      let param = {
        leader_id: this.leader_id,
        keyword: this.searchKey,
        page: this.page
      }
      let res = await this.$api.getGoodsList(param)
      if (!res) return

      if (this.page == 1) {
        this.goodsList = []
      }
      this.goodsList = this.goodsList.concat(res)
      if (res.length < 20) {
        this.isComplete = true
      } else {
        this.page++
      }
      this.pageScroll.endSuccess(res.length, !this.isComplete)
    },
    // 初始化滚动插件
    initialScroll () {
      let _this = this
      this.$nextTick(function () {
        this.pageScroll = new MeScroll(this.$refs.mescroll, {
          down: {
            isLock: true
          },
          up: {
            auto: false,
            callback: _this.getGoods,
            lazyLoad: {
              use: true
            },
            htmlNodata: '<p class="upwarp-nodata">已经到底了...</p>',
            noMoreSize: 10
          }
        })
      })
    }
  },
  components: {
    DiscountGoods,
    AddToCart
  }
}
</script>

<style lang="stylus" scoped>
.search
  position relative
  background #fff
  .search-input
    height 60px
    padding 10px 0
    border-bottom 1PX solid #efefef
    box-sizing border-box
    flexbox()
    align-items center
    .input-box
      flex-grow 1
      background #f2f2f2
      padding 10px 15px
      margin-left 15px
      flexbox()
      align-items center
      border-radius 20px
      .icon
        font-size 14px
        color #bbb
        background transparent
        position relative
        &:after
          content ''
          position absolute
          top -10px
          left -10px
          bottom -10px
          right -10px
      .input
        background transparent
        flex-grow 1
        padding 0 10px
    .btn
      padding 15px
      font-size 14px
  .search-list
    height calc(100% - 60px)
    .list
      padding 0 15px
      .goods-item
        width 100%
        flexbox()
        padding 15px 0
        border-bottom 1PX solid #efefef
        &:last-child
          border-bottom none
        .img-box
          width 80px
          height 80px
          overflow hidden
          flex-shrink 0
          position relative
          .goods-img
            width 100%
            height 100%
            object-fit cover
          .icon
            position absolute
            top 0
            left 0
            width 30px
            background $color-main
            &.txt-icon
              height 30px
              color #fff
              font-size 12px
              overflow hidden
              flexbox()
              align-items center
              justify-content center
            &.txt-icon.new-user
              box-sizing border-box
              padding-left 2px
              background -webkit-linear-gradient(top, #ff9204, #fe4022)
        .desc-box
          padding-left 10px
          flex-grow 1
          line-height 1.2
          position relative
          .name
            font-size 14px
            ellipsis(2)
            max-height 32px
          .total-buy
            margin 3px 0 5px
            color #999
          .group-buy
            font-size 10px
            background $color-main
            color #fff
            display inline-block
            padding 2px 8px
            border-radius 15px
          .price-box
            position absolute
            bottom -5px
            left 10px
            right 0px
            flexbox()
            justify-content space-between
            align-items center
            line-height 1.3
            .now
              font-size 18px
              font-weight bold
              color $color-main
              margin-right 5px
            .now-icon
              margin-right 0
              font-size 12px
            .old
              color #999999
              text-decoration line-through
            .num
              font-size 12px
              color #999999
            .cart-icon
              width 30px
              height 30px
              text-align center
              line-height 30px
              border-radius 50%
              background $color-main
              .icon.cart
                vertical-align middle
                color #ffffff
                font-size 22px
              .num-box
                color $color-main
                display none
                .num
                  color #000
                  padding 0 8px
                  font-size 16px
                  position relative
                  top -3px
                .icon
                  font-size 26px
                  position relative
                  &:after
                    content ''
                    position absolute
                    top -5px
                    left -5px
                    right -5px
                    bottom -5px
              &.active
                background #fff
                width auto
                .icon.cart
                  display none
                .num-box
                  display block
                .goods-item:last-child
                  border-bottom none
      .tip
        text-align center
        padding 15px 0
        color #999
    .history-box
      padding 0 15px
      .title
        flexbox()
        justify-content space-between
        align-items center
        font-size 16px
        font-weight 500
        .btn
          font-weight normal
          font-size 12px
          color #999
          padding 15px 0
          .icon
            /*font-size 12px*/
            padding-right 5px
            vertical-align middle
      .key-list
        flexbox()
        flex-wrap wrap
        .item
          margin-right 12px
          margin-bottom 12px
          border 1PX solid #e5e5e5
          color #666
          padding 8px 12px
          border-radius 4px
    .empty-list
      background #f8f8f8
      .empty-tip
        background #fff
        color #999
        text-align center
        padding 60px 0
        .img-box
          width 120px
          height 120px
          margin 0 auto 10px
          overflow hidden
          img
            width 100%
</style>
